        return board[0][2]

    # Check if the board is full
    is_full = True
    for row in board:
        for cell in row:
            if cell == '':
                is_full = False
                break
        if not is_full:
            break

    if is_full:
        return 'Draw'
    else:
        return 'Pending'
```

